/// Feed it one sample every 30 minutes (the app replays recorded NASA data this way).
class IssEnvMonitor {
  final List<List<double>> _hist = <List<double>>[];

  List<IssAssessment> addSample({
    required double co2,
    required double temperature,
    required double humidity,
    double? radiation,
  }) {
    final values = <double>[co2, temperature, humidity];
    List<double>? deltas;
    if (_hist.length >= IssEnvModel.historySteps) {
      deltas = IssEnvModel.forecastDeltas(_hist.sublist(_hist.length - IssEnvModel.historySteps));
    }
    final out = <IssAssessment>[];
    const vars = <IssVar>[IssVar.co2, IssVar.temperature, IssVar.humidity];
    for (var j = 0; j < 3; j++) {
      final v = vars[j];
      final b = IssEnvModel.bandsOf(v);
      var level = IssEnvModel.levelOf(v, values[j]);
      double? z;
      double? expected;
      var jump = false;
      if (_hist.length >= IssEnvModel.historySteps) {
        expected = _hist.last[j] + (deltas == null ? 0.0 : deltas[j]);
        z = (values[j] - expected) / IssEnvModel.sigma[j];
        jump = z.abs() > IssEnvModel.jumpLimit;
        if (jump && level == IssLevel.normal) level = z > 0 ? IssLevel.high : IssLevel.low;
      }
      out.add(IssAssessment(variable: v, value: values[j], level: level, jump: jump, normalLow: b[1], normalHigh: b[2], z: z, expected: expected));
    }
    if (radiation != null) {
      final b = IssEnvModel.radiationBands;
      out.add(IssAssessment(
        variable: IssVar.radiation,
        value: radiation,
        level: IssEnvModel.levelOf(IssVar.radiation, radiation),
        jump: false,
        normalLow: b[1],
        normalHigh: b[2],
      ));
    }
    _hist.add(values);
    if (_hist.length > IssEnvModel.historySteps) _hist.removeAt(0);
    return out;
  }

  void reset() => _hist.clear();
}
